-- Everything below is written by hand (3f design, section 6.1). As in 0016 to 0025: every function is owned by the
-- migrator, pins its search path, names every object schema-qualified and has EXECUTE taken from PUBLIC; a trigger
-- function fires for every role all the same; errors carry their code as the message under SQLSTATE P0001; times the
-- database writes are now(), the transaction's start, unless clock_timestamp() is named. "For every role but the
-- migrator" means current_user <> 'korbat_migrate'. No function here holds an interval literal: every number of 3f is
-- read from order_rules().
--
-- 1. The grants. 0001's default privileges gave the API role SELECT, INSERT, UPDATE and DELETE on every new public table;
-- each table first loses them all, then gets what section 6.1 lists. The watcher's role gets its four tables' grants
-- and EXECUTE on order_rules(), and nothing else anywhere. The API role keeps 0001's USAGE on the outbox's identity
-- sequence.
REVOKE ALL ON "public"."contact_messages", "public"."alert_outbox", "public"."notify_state", "public"."notify_folders" FROM korbat_api;--> statement-breakpoint
GRANT SELECT ON "public"."contact_messages" TO korbat_api;--> statement-breakpoint
GRANT UPDATE ("disposition", "handled_by") ON "public"."contact_messages" TO korbat_api;--> statement-breakpoint
GRANT INSERT ("folder", "uidvalidity", "uid", "received_at"), SELECT ON "public"."contact_messages" TO korbat_notify;--> statement-breakpoint
GRANT INSERT, SELECT ON "public"."alert_outbox" TO korbat_api;--> statement-breakpoint
GRANT UPDATE ("mailed_at") ON "public"."alert_outbox" TO korbat_api;--> statement-breakpoint
GRANT SELECT ON "public"."alert_outbox" TO korbat_notify;--> statement-breakpoint
GRANT UPDATE ("pushed_at", "push_attempts") ON "public"."alert_outbox" TO korbat_notify;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "public"."notify_state", "public"."notify_folders" TO korbat_notify;--> statement-breakpoint
GRANT SELECT ON "public"."notify_state", "public"."notify_folders" TO korbat_api;--> statement-breakpoint
-- 2. The constants of 3f, one row of named values; the contracts' ORDER_RULES holds the same, and a database test
-- compares the two name by name. Every function and view of 3f reads its numbers from here, the alert numbers and the
-- retention periods among them. Each is a cautious default flagged for the owner (3f design, section 2): one line to
-- change. unconfirmed_hold_hours is null: no shorter hold for a tick nobody has confirmed.
CREATE FUNCTION "public"."order_rules"() RETURNS TABLE (
  hour_minutes integer, target_minutes integer, items_per_action integer, decisions_per_day integer, records_per_day integer,
  hold_days integer, hold_extension_days integer, hold_warning_days integer, unconfirmed_hold_hours integer,
  preserve_months integer, preserve_margin_days integer, report_hold_days integer, report_alert_hours integer,
  stale_hours integer, quiet_minutes integer, escalate_minutes integer, remind_minutes integer,
  channel_down_minutes integer, push_owed_minutes integer, copy_overdue_hours integer, handover_alert_days integer,
  message_keep_days integer, record_keep_years integer, gap_keep_months integer)
LANGUAGE sql IMMUTABLE SET search_path = public, pg_temp AS $$
  SELECT 60, 55, 10, 50, 20, 43, 42, 7, NULL::integer, 6, 1, 7, 24, 2, 15, 15, 45, 3, 60, 48, 7, 30, 3, 12
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."order_rules"() FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "public"."order_rules"() TO korbat_api, korbat_notify;--> statement-breakpoint
-- An instant as an alert's facts hold it: ISO 8601 in UTC with a final Z, the form alert_outbox_facts takes and the
-- contracts' renderAlert reads. Only the functions below call it.
CREATE FUNCTION "public"."alert_time"(at timestamptz) RETURNS text
LANGUAGE sql STABLE SET search_path = public, pg_temp AS $$
  SELECT (pg_catalog.to_jsonb(at AT TIME ZONE 'UTC') #>> '{}') || 'Z'
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_time"(timestamptz) FROM PUBLIC;--> statement-breakpoint
-- 3. contact_messages. A message's row is forced for every role but the migrator: seen_at is the clock's time; a
-- received_at ahead of the clock is stored as the clock's time (a mail host a few seconds ahead would otherwise give an
-- order opened from the message at once a raw CHECK failure; the lesser only moves a deadline earlier); stale says that
-- korbat first saw it more than stale_hours after it arrived; and nobody has handled it yet. The migrator (a restore's
-- import, a test's fixture) keeps what it supplied, and what it left out is set as for anyone.
CREATE FUNCTION "public"."contact_messages_insert"() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_stale integer;
BEGIN
  SELECT r.stale_hours INTO v_stale FROM public.order_rules() r;
  IF current_user <> 'korbat_migrate' THEN
    NEW.seen_at := v_now;
    NEW.received_at := least(NEW.received_at, v_now);
    NEW.stale := NEW.received_at < v_now - make_interval(hours => v_stale);
    NEW.disposition := NULL;
    NEW.handled_by := NULL;
    NEW.handled_at := NULL;
  ELSE
    NEW.seen_at := coalesce(NEW.seen_at, v_now);
    NEW.stale := coalesce(NEW.stale, NEW.received_at < NEW.seen_at - make_interval(hours => v_stale));
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."contact_messages_insert"() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER "contact_messages_insert" BEFORE INSERT ON "public"."contact_messages" FOR EACH ROW EXECUTE FUNCTION "public"."contact_messages_insert"();--> statement-breakpoint
-- A disposition that is set never changes, nor who set it (message_handled): a mistake is corrected by what follows it,
-- an order opened from the message all the same. Setting one needs the staff member who set it, and stamps when. For
-- every role but the migrator: a definer function that sets a disposition as its owner (Task 2's order_event_record)
-- stamps handled_at itself. The API role may update only these two columns (section 1 above).
CREATE FUNCTION "public"."contact_messages_guard"() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
BEGIN
  IF current_user = 'korbat_migrate' THEN
    RETURN NEW;
  END IF;
  IF OLD.disposition IS NOT NULL THEN
    IF NEW.disposition IS DISTINCT FROM OLD.disposition OR NEW.handled_by IS DISTINCT FROM OLD.handled_by THEN
      RAISE EXCEPTION 'message_handled';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.disposition IS NULL THEN
    -- Nothing is handled, so nobody is recorded as having handled it.
    IF NEW.handled_by IS NOT NULL THEN
      RAISE EXCEPTION 'invalid_request';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.handled_by IS NULL THEN
    RAISE EXCEPTION 'invalid_request';
  END IF;
  NEW.handled_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."contact_messages_guard"() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER "contact_messages_guard" BEFORE UPDATE ON "public"."contact_messages" FOR EACH ROW EXECUTE FUNCTION "public"."contact_messages_guard"();--> statement-breakpoint
-- The first push of a message needs neither the API nor a job: unless the message is stale, its insert writes the
-- outbox row of kind contact_mail, step 0, priority 5, to the phone on call, with the time of receipt and the deadline
-- it would have as an order. The bound on a flood: no step-0 row while another message that is not stale has no
-- disposition and its own step-0 row is younger than quiet_minutes. The person already awake reads the whole mailbox,
-- and the first message's deadline is the earlier one; the message's own row is written all the same, and its
-- escalation and its order_due run as for any message, so nothing is dropped. With quiet_minutes 0 every message rings.
CREATE FUNCTION "public"."contact_messages_alert"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_quiet integer;
  v_hour integer;
BEGIN
  IF NEW.stale THEN
    RETURN NULL;
  END IF;
  SELECT r.quiet_minutes, r.hour_minutes INTO v_quiet, v_hour FROM public.order_rules() r;
  IF EXISTS (SELECT 1 FROM public.contact_messages m
               JOIN public.alert_outbox o ON o.kind = 'contact_mail' AND o.message_id = m.id AND o.step = 0
              WHERE m.id <> NEW.id AND NOT m.stale AND m.disposition IS NULL
                AND o.created_at > clock_timestamp() - make_interval(mins => v_quiet)) THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.alert_outbox (kind, priority, scope, step, facts, message_id)
  VALUES ('contact_mail', 5, 'on_call', 0,
          jsonb_build_object('receivedAt', public.alert_time(NEW.received_at), 'dueAt', public.alert_time(NEW.received_at + make_interval(mins => v_hour))),
          NEW.id)
  ON CONFLICT DO NOTHING;
  RETURN NULL;
END $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."contact_messages_alert"() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER "contact_messages_alert" AFTER INSERT ON "public"."contact_messages" FOR EACH ROW EXECUTE FUNCTION "public"."contact_messages_alert"();--> statement-breakpoint
-- 4. alert_outbox. A row's time and its two legs are forced at insert for every role: it is created now, owed its push
-- and its mail, and tried no time yet. The unique key of a time-driven alert's step, which drizzle cannot write: one
-- row a kind, subject and step, a missing subject counting as one subject (NULLS NOT DISTINCT), so a concurrent call of
-- alert_steps() that wrote the same step makes the second insert do nothing.
CREATE FUNCTION "public"."alert_outbox_insert"() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
BEGIN
  NEW.created_at := clock_timestamp();
  NEW.pushed_at := NULL;
  NEW.mailed_at := NULL;
  NEW.push_attempts := 0;
  RETURN NEW;
END $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_outbox_insert"() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER "alert_outbox_insert" BEFORE INSERT ON "public"."alert_outbox" FOR EACH ROW EXECUTE FUNCTION "public"."alert_outbox_insert"();--> statement-breakpoint
CREATE UNIQUE INDEX "alert_outbox_step_key" ON "public"."alert_outbox" USING btree ("kind", "message_id", "order_id", "step") NULLS NOT DISTINCT WHERE step IS NOT NULL;--> statement-breakpoint
-- 5. alert_steps(): every time-driven alert, as inserts into alert_outbox, by one rule: a row is written when its
-- condition holds and no row of the same kind and subject was created at or after its threshold. Its step is the
-- subject's highest step of that kind plus one, counted for each kind by itself, and the unique key drops what a
-- concurrent call wrote. Answers how many rows it wrote. The alert tick calls it every round; the later migrations of
-- 3f replace it, each adding the rows of its task. A daily kind's threshold is "a day ago": the function fixes no hour of
-- the day. The channel's two alarms are the tick's own rows, not this function's, so that NOTIFY=off can skip them.
--   - contact_mail_escalated: a message that is not stale and has no disposition, received escalate_minutes ago or
--     more, when no staff session was created or used since it arrived (auth.staff_sessions.last_used_at is a person's
--     own action in the console, never a request the page sent by itself); once a message.
--   - order_due for a message: one row at received_at + remind_minutes and one at the deadline it would have as an
--     order, received_at + hour_minutes, the later of the two that has passed; with the deadline and the minutes left.
--   - alert_test: daily, pushed only.
-- Its search path holds public alone, as every function the migrator owns does (the moderation schema test pins it):
-- auth's one table is named in full.
CREATE FUNCTION "public"."alert_steps"() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_now timestamptz := now();
  r record;
  v_rows integer;
  v_written integer := 0;
BEGIN
  SELECT * INTO r FROM public.order_rules();

  INSERT INTO public.alert_outbox (kind, priority, scope, step, facts, message_id)
  SELECT 'contact_mail_escalated', 5, 'all',
         coalesce((SELECT max(o.step) + 1 FROM public.alert_outbox o
                    WHERE o.kind = 'contact_mail_escalated' AND o.message_id = m.id AND o.order_id IS NULL), 0),
         jsonb_build_object('receivedAt', public.alert_time(m.received_at), 'dueAt', public.alert_time(m.received_at + make_interval(mins => r.hour_minutes))),
         m.id
    FROM public.contact_messages m
   WHERE NOT m.stale AND m.disposition IS NULL
     AND m.received_at + make_interval(mins => r.escalate_minutes) <= v_now
     AND NOT EXISTS (SELECT 1 FROM auth.staff_sessions s WHERE s.created_at >= m.received_at OR s.last_used_at >= m.received_at)
     AND NOT EXISTS (SELECT 1 FROM public.alert_outbox o
                      WHERE o.kind = 'contact_mail_escalated' AND o.message_id = m.id AND o.order_id IS NULL
                        AND o.created_at >= m.received_at + make_interval(mins => r.escalate_minutes))
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_written := v_written + v_rows;

  INSERT INTO public.alert_outbox (kind, priority, scope, step, facts, message_id)
  SELECT 'order_due', 5, 'all',
         coalesce((SELECT max(o.step) + 1 FROM public.alert_outbox o
                    WHERE o.kind = 'order_due' AND o.message_id = m.id AND o.order_id IS NULL), 0),
         -- The minutes left, rounded up and never below 0: an hour of order_rules() is hour_minutes minutes.
         jsonb_build_object('dueAt', public.alert_time(d.due_at),
                            'minutesLeft', greatest(0, ceil(extract(epoch FROM d.due_at - v_now) / extract(epoch FROM make_interval(mins => r.hour_minutes)) * r.hour_minutes))::integer),
         m.id
    FROM public.contact_messages m
   CROSS JOIN LATERAL (
     SELECT m.received_at + make_interval(mins => r.hour_minutes) AS due_at,
            CASE WHEN m.received_at + make_interval(mins => r.hour_minutes) <= v_now THEN m.received_at + make_interval(mins => r.hour_minutes)
                 WHEN m.received_at + make_interval(mins => r.remind_minutes) <= v_now THEN m.received_at + make_interval(mins => r.remind_minutes)
            END AS threshold) d
   WHERE NOT m.stale AND m.disposition IS NULL AND d.threshold IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.alert_outbox o
                      WHERE o.kind = 'order_due' AND o.message_id = m.id AND o.order_id IS NULL AND o.created_at >= d.threshold)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_written := v_written + v_rows;

  INSERT INTO public.alert_outbox (kind, priority, scope, step, facts)
  SELECT 'alert_test', 3, 'all',
         coalesce((SELECT max(o.step) + 1 FROM public.alert_outbox o
                    WHERE o.kind = 'alert_test' AND o.message_id IS NULL AND o.order_id IS NULL), 0),
         jsonb_build_object('at', public.alert_time(v_now))
   WHERE NOT EXISTS (SELECT 1 FROM public.alert_outbox o
                      WHERE o.kind = 'alert_test' AND o.message_id IS NULL AND o.order_id IS NULL AND o.created_at >= v_now - make_interval(days => 1))
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_written := v_written + v_rows;

  RETURN v_written;
END $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_steps"() FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "public"."alert_steps"() TO korbat_api;
